import {
  ComponentType,
  Overlay,
  OverlayConfig,
  OverlayContainer,
  OverlayRef,
} from '@angular/cdk/overlay';
import { ComponentPortal, TemplatePortal } from '@angular/cdk/portal';

import {
  ComponentRef,
  DOCUMENT,
  EmbeddedViewRef,
  Injectable,
  InjectionToken,
  Injector,
  OnDestroy,
  TemplateRef,
  ViewContainerRef,
  inject,
} from '@angular/core';
import {
  QDestroyService,
  QSharedMutationObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs';
import { QToastConfig } from './toast-config';
import { QToastRef } from './toast-ref';
import { QToastSimpleComponent } from './toast-simple';
import { QToastComponent } from './toast.component';
import { Q_TOAST_DATA } from './types/toast-data.const';
import { QTextOnlyToast } from './types/toast-text-only.interface';

export function Q_TOAST_DEFAULT_OPTIONS_FACTORY(): QToastConfig {
  return new QToastConfig();
}

export const Q_TOAST_DEFAULT_OPTIONS = new InjectionToken<QToastConfig>('q-toast-default-options', {
  providedIn: 'root',
  factory: Q_TOAST_DEFAULT_OPTIONS_FACTORY,
});

@Injectable()
export class QToast implements OnDestroy {
  private _toastRefAtThisLevel: QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> | null =
    null;
  private _toastSimpleComponent = QToastSimpleComponent;
  private _toastContainerComponent = QToastComponent;
  private _dismissTimeout = 10000;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _overlayContainer = inject(OverlayContainer);
  private readonly _sharedMutationObserverService = inject(QSharedMutationObserverService);
  private readonly _document = inject(DOCUMENT);
  private readonly _overlay = inject(Overlay);
  private readonly _injector = inject(Injector);
  private readonly _parentToast = inject(QToast, { optional: true, skipSelf: true });
  private readonly _defaultConfig = inject<QToastConfig>(Q_TOAST_DEFAULT_OPTIONS);

  get _openedToastRef(): QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> | null {
    const parent = this._parentToast;
    return parent ? parent._openedToastRef : this._toastRefAtThisLevel;
  }
  set _openedToastRef(value: QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> | null) {
    if (this._parentToast) {
      this._parentToast._openedToastRef = value;
    } else {
      this._toastRefAtThisLevel = value;
    }
  }

  ngOnDestroy(): void {
    if (this._toastRefAtThisLevel) {
      this._toastRefAtThisLevel.dismiss();
    }
  }

  openFromComponent(
    component: ComponentType<QTextOnlyToast>,
    config?: QToastConfig,
  ): QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> {
    return this._attach(component, config) as QToastRef<
      QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>
    >;
  }

  open(
    message: string,
    action = '',
    actionAdditional = '',
    config?: QToastConfig,
  ): QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> {
    const _config = { ...this._defaultConfig, ...config } as QToastConfig;

    _config.data = {
      message,
      action,
      actionAdditional,
      icon: config?.icon || '',
      dismissIcon: config?.dismissIcon || this._defaultConfig.dismissIcon || false,
      buttonType: config?.buttonType || this._defaultConfig.buttonType,
      buttonAdditionalType:
        config?.buttonAdditionalType || this._defaultConfig.buttonAdditionalType,
      buttonsPosition: config?.buttonsPosition || this._defaultConfig.buttonsPosition,
    };

    return this.openFromComponent(
      this._toastSimpleComponent as ComponentType<QTextOnlyToast>,
      _config,
    );
  }

  dismiss(): void {
    if (this._openedToastRef) {
      this._openedToastRef.dismiss();
    }
  }

  private _attachToastContainer(overlayRef: OverlayRef, config: QToastConfig): QToastComponent {
    const userInjector = config && config.viewContainerRef && config.viewContainerRef.injector;
    const injector = Injector.create({
      parent: userInjector || this._injector,
      providers: [{ provide: QToastConfig, useValue: config }],
    });
    const containerPortal = new ComponentPortal(
      this._toastContainerComponent,
      config.viewContainerRef,
      injector,
    );
    const containerRef: ComponentRef<QToastComponent> = overlayRef.attach(containerPortal);

    containerRef.instance.toastConfig = config;

    return containerRef.instance;
  }

  private _attach(
    content: ComponentType<QTextOnlyToast> | TemplateRef<QTextOnlyToast>,
    userConfig?: QToastConfig,
  ): QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>> {
    const config = { ...new QToastConfig(), ...this._defaultConfig, ...userConfig };
    const overlayRef = this._createOverlay(config);
    const container = this._attachToastContainer(overlayRef, config);
    const toastRef = new QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>>(
      container,
      overlayRef,
    );

    if (content instanceof TemplateRef) {
      const portal = new TemplatePortal(
        content,
        null as unknown as ViewContainerRef,
        { $implicit: config.data, toastRef } as unknown as QTextOnlyToast,
      );

      toastRef.instance = container.attachTemplatePortal<QTextOnlyToast>(portal);
    } else {
      const injector = this._createInjector(config, toastRef);
      const portal = new ComponentPortal(content, undefined, injector);
      const contentRef = container.attachComponentPortal<QTextOnlyToast>(portal);

      toastRef.instance = contentRef.instance;
    }
    const overlayContainer = this._overlayContainer.getContainerElement();

    if (config.sourceDialogElement) {
      overlayContainer.parentNode?.removeChild(overlayContainer);
      config.sourceDialogElement.appendChild(overlayContainer);

      this._sharedMutationObserverService
        .observe(config.sourceDialogElement, { attributes: true })
        ?.pipe(takeUntil(this._destroy$))
        .subscribe((mutations: MutationRecord[]) => {
          mutations.forEach((mutation: MutationRecord) => {
            const dialogElement = mutation.target as HTMLElement;

            if (dialogElement.hasAttribute('open')) {
              overlayContainer.parentNode?.removeChild(overlayContainer);
              config.sourceDialogElement?.appendChild(overlayContainer);
            } else if (overlayContainer.parentNode !== this._document.body) {
              overlayContainer.parentNode?.removeChild(overlayContainer);
              this._document.body.appendChild(overlayContainer);
            }
          });
        });
    } else if (config.sourcePopoverElement) {
      overlayContainer.parentNode?.removeChild(overlayContainer);
      config.sourcePopoverElement.appendChild(overlayContainer);

      const handlePopoverToggle = (event: Event): void => {
        const toggleEvent = event as ToggleEvent;

        if (toggleEvent.newState === 'open') {
          overlayContainer.parentNode?.removeChild(overlayContainer);
          config.sourcePopoverElement?.appendChild(overlayContainer);
        } else if (
          toggleEvent.newState === 'closed' &&
          overlayContainer.parentNode !== this._document.body
        ) {
          overlayContainer.parentNode?.removeChild(overlayContainer);
          this._document.body.appendChild(overlayContainer);
        }
      };

      config.sourcePopoverElement.addEventListener('beforetoggle', handlePopoverToggle);

      toastRef
        .afterDismissed()
        .pipe(takeUntil(this._destroy$))
        .subscribe(() => {
          config.sourcePopoverElement?.removeEventListener('beforetoggle', handlePopoverToggle);
        });
    } else if (overlayContainer.parentNode !== this._document.body) {
      this._document.body.appendChild(overlayContainer);
    }

    this._animateToast(toastRef, config);
    this._openedToastRef = toastRef;

    return this._openedToastRef;
  }

  private _animateToast(
    toastRef: QToastRef<QTextOnlyToast | EmbeddedViewRef<QTextOnlyToast>>,
    config: QToastConfig,
  ): void {
    toastRef
      .afterDismissed()
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        if (this._openedToastRef === toastRef) {
          this._openedToastRef = null;
        }
      });

    if (this._openedToastRef) {
      this._openedToastRef
        .afterDismissed()
        .pipe(takeUntil(this._destroy$))
        .subscribe(() => {
          toastRef.containerInstance.enter();
        });
      this._openedToastRef.dismiss();
    } else {
      toastRef.containerInstance.enter();
    }

    if (config.autoDismiss) {
      toastRef
        .afterOpened()
        .pipe(takeUntil(this._destroy$))
        .subscribe(() => toastRef._dismissAfter(this._dismissTimeout));
    }
  }

  private _createOverlay(config: QToastConfig): OverlayRef {
    const overlayConfig = new OverlayConfig();
    const positionStrategy = this._overlay.position().global();
    const isLeft = config.horizontalPosition === 'left';
    const isRight = !isLeft && config.horizontalPosition !== 'center';

    if (isLeft) {
      positionStrategy.left('0');
    } else if (isRight) {
      positionStrategy.right('0');
    } else {
      positionStrategy.centerHorizontally();
    }

    if (config.verticalPosition === 'top') {
      positionStrategy.top('0');
    } else {
      positionStrategy.bottom('0');
    }

    if (
      config.dismissIcon &&
      config.size === 'standard' &&
      config.buttonsPosition === 'side' &&
      config.data &&
      config.data.action &&
      config.data.actionAdditional
    ) {
      config.data.buttonsPosition = 'bottom';
      config.buttonsPosition = 'bottom';
    }

    overlayConfig.positionStrategy = positionStrategy;

    return this._overlay.create(overlayConfig);
  }

  private _createInjector<T>(config: QToastConfig, toastRef: QToastRef<T>): Injector {
    const userInjector = config && config.viewContainerRef && config.viewContainerRef.injector;

    return Injector.create({
      parent: userInjector || this._injector,
      providers: [
        { provide: QToastRef, useValue: toastRef },
        { provide: Q_TOAST_DATA, useValue: config.data },
      ],
    });
  }
}
