import { AnimationEvent } from '@angular/animations';
import {
  BasePortalOutlet,
  CdkPortalOutlet,
  ComponentPortal,
  DomPortal,
  TemplatePortal,
} from '@angular/cdk/portal';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentRef,
  ElementRef,
  EmbeddedViewRef,
  HostBinding,
  Input,
  NgZone,
  OnDestroy,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { Observable, Subject } from 'rxjs';
import { take } from 'rxjs/operators';
import { QToastConfig } from './toast-config';
import { toastAnimation } from './toast.animation';

@Component({
  selector: 'q-toast',
  imports: [CdkPortalOutlet],
  templateUrl: './toast.component.html',
  styleUrls: ['./toast.component.scss'],
  encapsulation: ViewEncapsulation.None,
  animations: [toastAnimation.toastState],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    class: 'q-toast q-toast-container q-toast--open',
    '[class.q-toast-has-left-icon]': 'hasLeftIcon',
    '[class.q-toast-has-right-actions]': 'hasRightActions',
    '[@state]': '_animationState',
    '(@state.done)': 'onAnimationEnd($event)',
  },
})
export class QToastComponent extends BasePortalOutlet implements OnDestroy {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-toast';

  @ViewChild(CdkPortalOutlet, { static: true }) _portalOutlet!: CdkPortalOutlet;

  _animationState = 'void';
  toastConfig = inject(QToastConfig);
  readonly _onExit = new Subject<void>();
  readonly _onEnter = new Subject<void>();

  protected _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);

  private _destroyed = false;
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private readonly _ngZone = inject(NgZone);

  constructor() {
    super();
  }

  ngOnDestroy(): void {
    this._destroyed = true;
    this._completeExit();
  }

  attachComponentPortal<T>(portal: ComponentPortal<T>): ComponentRef<T> {
    this._assertNotAttached();
    const result = this._portalOutlet.attachComponentPortal(portal);

    this._afterPortalAttached();

    return result;
  }

  attachTemplatePortal<C>(portal: TemplatePortal<C>): EmbeddedViewRef<C> {
    this._assertNotAttached();
    const result = this._portalOutlet.attachTemplatePortal(portal);

    this._afterPortalAttached();

    return result;
  }

  override attachDomPortal = (portal: DomPortal): void => {
    this._assertNotAttached();
    const result = this._portalOutlet.attachDomPortal(portal);

    this._afterPortalAttached();

    return result;
  };

  onAnimationEnd(event: AnimationEvent): void {
    const { fromState, toState } = event;

    if ((toState === 'void' && fromState !== 'void') || toState === 'hidden') {
      this._completeExit();
    }

    if (toState === 'visible') {
      const onEnter = this._onEnter;

      onEnter.next();
      onEnter.complete();
    }
  }

  enter(): void {
    if (!this._destroyed) {
      this._animationState = 'visible';
      this._changeDetectorRef.detectChanges();
    }
  }

  exit(): Observable<void> {
    this._ngZone.run(() => {
      this._animationState = 'hidden';

      this._elementRef.nativeElement.setAttribute('q-exit', '');
      this._changeDetectorRef.markForCheck();
    });

    return this._onExit;
  }

  protected _afterPortalAttached(): void {
    const element: HTMLElement = this._elementRef.nativeElement;
    const panelType = this.toastConfig.type;
    const toastSize = this.toastConfig.size;
    const buttonsPositionClass = `buttons-position-${this.toastConfig.buttonsPosition}`;

    element.classList.add(
      `q-toast-${panelType}`,
      `q-toast-${toastSize}`,
      `q-toast-${buttonsPositionClass}`,
    );
  }

  get hasLeftIcon(): boolean {
    return !!this.toastConfig?.data?.icon;
  }

  get hasRightActions(): boolean {
    return (
      ((!!this.toastConfig?.data?.action || !!this.toastConfig?.data?.actionAdditional) &&
        this.toastConfig?.buttonsPosition === 'side') ||
      !!this.toastConfig?.data?.dismissIcon
    );
  }

  private _completeExit(): void {
    this._ngZone.onMicrotaskEmpty.pipe(take(1)).subscribe(() => {
      this._ngZone.run(() => {
        this._onExit.next();
        this._onExit.complete();
      });
    });
  }

  private _assertNotAttached(): void {
    if (this._portalOutlet.hasAttached()) {
      throw Error('Attempting to attach toast content after content is already attached');
    }
  }
}
