import { OverlayRef } from '@angular/cdk/overlay';
import { Observable, Subject } from 'rxjs';
import { QToastComponent } from './toast.component';
import { QToastDismiss } from './types/toast-dismiss.interface';

const MAX_TIMEOUT = Math.pow(2, 31) - 1;

export class QToastRef<T> {
  instance!: T;

  private readonly _afterDismissed = new Subject<QToastDismiss>();
  private readonly _afterOpened = new Subject<void>();
  private readonly _onAction = new Subject<void>();
  private _durationTimeoutId!: number;
  private _dismissedByAction = false;

  constructor(
    public containerInstance: QToastComponent,
    private _overlayRef: OverlayRef,
  ) {
    this.containerInstance._onExit.subscribe(() => this._finishDismiss());
  }

  dismiss(): void {
    if (!this._afterDismissed.closed) {
      this.containerInstance.exit();
    }

    clearTimeout(this._durationTimeoutId);
  }

  dismissWithAction(): void {
    if (!this._onAction.closed) {
      this._dismissedByAction = true;
      this._onAction.next();
      this._onAction.complete();
      this.dismiss();
    }

    clearTimeout(this._durationTimeoutId);
  }

  closeWithAction(): void {
    this.dismissWithAction();
  }

  _dismissAfter(duration: number): void {
    this._durationTimeoutId = window.setTimeout(
      () => this.dismiss(),
      Math.min(duration, MAX_TIMEOUT),
    );
  }

  _open(): void {
    if (!this._afterOpened.closed) {
      this._afterOpened.next();
      this._afterOpened.complete();
    }
  }

  afterDismissed(): Observable<QToastDismiss> {
    return this._afterDismissed;
  }

  afterOpened(): Observable<void> {
    return this.containerInstance._onEnter;
  }

  onAction(): Observable<void> {
    return this._onAction;
  }

  private _finishDismiss(): void {
    this._overlayRef.dispose();

    if (!this._onAction.closed) {
      this._onAction.complete();
    }

    this._afterDismissed.next({ dismissedByAction: this._dismissedByAction });
    this._afterDismissed.complete();
    this._dismissedByAction = false;
  }
}
