import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Output,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QButtonComponent, QButtonVariant } from '@questrade/allspark-angular-components/button';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { clear } from '@questrade/allspark-icons/icons';
import { QToastActionDirective } from './toast-action.directive';
import { QToastActionsDirective } from './toast-actions.directive';
import { QToastLabelDirective } from './toast-label.directive';
import { QToastRef } from './toast-ref';
import { QToastButtonsPosition } from './types/toast-buttons-position.type';
import { QToastConfigData } from './types/toast-config-data.interface';
import { Q_TOAST_DATA } from './types/toast-data.const';
import { QTextOnlyToast } from './types/toast-text-only.interface';

@Component({
  selector: 'q-toast-simple',
  imports: [
    NgIf,
    NgTemplateOutlet,
    QIconComponent,
    QInteractiveIconComponent,
    QButtonComponent,
    QToastLabelDirective,
    QToastActionDirective,
    QToastActionsDirective,
  ],
  templateUrl: './toast-simple.html',
  styleUrls: ['./toast-simple.scss'],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QToastSimpleComponent implements QTextOnlyToast {
  @Output() readonly actionClicked = new EventEmitter<void>();
  @Output() readonly additionalActionClicked = new EventEmitter<void>();
  @Output() readonly closeIconClicked = new EventEmitter<void>();

  @HostBinding('class') hostClass = 'q-toast-simple';

  iconName = '';
  actionsPosition: QToastButtonsPosition = 'side';
  data = inject<QToastConfigData>(Q_TOAST_DATA);
  toastRef = inject<QToastRef<QToastSimpleComponent>>(QToastRef);

  private readonly _iconRegistry = inject(QIconRegistryService);

  constructor() {
    const data = this.data;
    const _iconRegistry = this._iconRegistry;

    _iconRegistry.registerIcon(clear);

    if (data.icon) {
      this.iconName = data.icon;
    }

    if (data.buttonsPosition) {
      this.actionsPosition = data.buttonsPosition;
    }
  }

  dismiss(): void {
    this.toastRef.dismissWithAction();
  }

  actionClick(): void {
    this.actionClicked.emit();
    this.dismiss();
  }

  additionalActionClick(): void {
    this.additionalActionClicked.emit();
    this.dismiss();
  }

  closeIconClick(): void {
    this.closeIconClicked.emit();
    this.dismiss();
  }

  get hasAction(): boolean {
    return !!this.data.action;
  }

  get hasActionAdditional(): boolean {
    return !!this.data.actionAdditional;
  }

  get isDismissible(): boolean {
    return !!this.data.dismissIcon;
  }

  get isTextButtonType(): boolean {
    return this.data.buttonType.includes('text');
  }

  get isTextButtonAdditionalType(): boolean {
    return this.data.buttonAdditionalType.includes('text');
  }

  get buttonVariant(): QButtonVariant {
    return this.data.buttonType.split(' ')[0] as QButtonVariant;
  }

  get buttonAdditionalVariant(): QButtonVariant {
    return this.data.buttonAdditionalType.split(' ')[0] as QButtonVariant;
  }
}
